// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/payments/tenants/{tenantId}/topup-details", wrapper.GetTopupDetails)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/payments/tenants/{tenantId}/topups", wrapper.CreateTopup)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/payments/tenants/{tenantId}/topups/{topupId}", wrapper.GetTopup)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/payments/callbacks/daraja/{railAccountId}/{token}/stk", wrapper.ReceiveStkCallback)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/payments/callbacks/daraja/{railAccountId}/{token}/c2b/validation", wrapper.ReceiveC2bValidation)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/payments/callbacks/daraja/{railAccountId}/{token}/c2b/confirmation", wrapper.ReceiveC2bConfirmation)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/payments/staff/suspense", wrapper.ListSuspense)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/payments/staff/collection-notices/{noticeId}/match", wrapper.MatchCollectionNotice)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/payments/staff/statement-imports", wrapper.CreateStatementImport)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/payments/staff/recon-exceptions", wrapper.ListReconExceptions)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/payments/staff/recon-exceptions/{exceptionId}/resolution", wrapper.ResolveReconException)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/payments/tenants/{tenantId}/checkout-links", wrapper.CreateCheckoutLink)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/payments/checkout/{token}", wrapper.GetCheckout)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/payments/checkout/{token}/payments", wrapper.CreateCheckoutPayment)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/payments/checkout/{token}/payments/{paymentId}", wrapper.GetCheckoutPayment)
	})

	return r
}

